WITH filtered_departments AS (SELECT * FROM departments WHERE dept_name IN ('Legal', 'Sales')), budget_bucket_summary AS (SELECT CASE WHEN budget >= 3359000 THEN 'high' WHEN budget >= 2039000 THEN 'mid' ELSE 'low' END budget_bucket, MAX(budget) - MIN(budget) budget_range FROM filtered_departments GROUP BY CASE WHEN budget >= 3359000 THEN 'high' WHEN budget >= 2039000 THEN 'mid' ELSE 'low' END) SELECT * FROM budget_bucket_summary WHERE budget_range >= 65 ORDER BY budget_range ASC
